from fractions import Fraction

CASES = [
    [1, 2, 2, 4],
    [-1, 3, 1, -3],
    [0, 5, 0, 7],
    [355, 113, 71, 22],
    [-7, 12, -5, 9],
    [10, -4, -5, 2],
    [1, 3, 999999999999, 3000000000000],
    [2, 7, 3, 11],
    [-1, 1000000007, 1, -1000000007],
]

GUARD_CASES = [
    [1, 0, 2, 3],
    [2, 3, 5, 0],
]

def cmp_cross(an, ad, bn, bd):
    if ad == 0 or bd == 0:
        raise ArithmeticError('zero denominator: unresolved, abort')
    lhs = an * bd
    rhs = bn * ad
    if lhs < rhs:
        return -1
    if lhs > rhs:
        return 1
    return 0

def cmp_frac(x, y):
    if x < y: return -1
    if x > y: return 1
    return 0

def verify():
    for c in GUARD_CASES:
        try:
            cmp_cross(c[0], c[1], c[2], c[3])
            return 'FAIL'
        except ArithmeticError:
            pass
    for c in CASES:
        an, ad, bn, bd = c
        got = cmp_cross(an, ad, bn, bd)
        want = cmp_frac(Fraction(an, ad), Fraction(bn, bd))
        if got != want:
            return 'FAIL'
        if got == 0 and Fraction(an, ad) != Fraction(bn, bd):
            return 'FAIL'
        if got != 0 and Fraction(an, ad) == Fraction(bn, bd):
            return 'FAIL'
    return 'PASS'

RESULT = verify()
